using System;
using System.Threading.Tasks;
using StackExchange.Redis;

namespace ProductService.Cache;

public sealed class ProductViewsCache
{
    private const string KeyPrefix = "views:product:";

    private readonly IConnectionMultiplexer _connection;

    public ProductViewsCache(IConnectionMultiplexer connection)
    {
        _connection = connection;
    }

    public async Task<long> GetAsync(string key)
    {
        var db = _connection.GetDatabase();
        var raw = await db.StringGetAsync(CacheHelpers.BuildKey(KeyPrefix, key)).ConfigureAwait(false);
        return raw.IsNullOrEmpty ? 0L : (long)raw;
    }

    public async Task<long> IncrementAsync(string key, long amount = 1)
    {
        var db = _connection.GetDatabase();
        var cacheKey = CacheHelpers.BuildKey(KeyPrefix, key);
        var result = await db.StringIncrementAsync(cacheKey, amount).ConfigureAwait(false);
        return result;
    }

    public async Task<long> DecrementAsync(string key, long amount = 1)
    {
        var db = _connection.GetDatabase();
        return await db.StringDecrementAsync(CacheHelpers.BuildKey(KeyPrefix, key), amount).ConfigureAwait(false);
    }

    /// <summary>Set the counter to an absolute value. Backs the DSL's
    /// `{block}.{Entry}.set(key, value)` form, distinct from the relative
    /// Increment/Decrement above.</summary>
    public async Task SetAsync(string key, long value)
    {
        var db = _connection.GetDatabase();
        var cacheKey = CacheHelpers.BuildKey(KeyPrefix, key);
        await db.StringSetAsync(cacheKey, value).ConfigureAwait(false);
    }

    public async Task ResetAsync(string key)
    {
        var db = _connection.GetDatabase();
        await db.KeyDeleteAsync(CacheHelpers.BuildKey(KeyPrefix, key)).ConfigureAwait(false);
    }
